            diff_positions.append(i)

    # Check if we're adding or removing characters
    if len(inp) != len(out):
        print(f"  Length change: {len(inp)} -> {len(out)}")
        if len(out) > len(inp):
            print(f"  Added characters at end")
        else:
            print(f"  Removed characters at end")

    # Show what's different
    if diff_positions:
        print(f"  Differences at positions: {diff_positions}")
        for pos in diff_positions:
            if pos < len(inp) and pos < len(out):
                print(f"    Position {pos}: '{inp[pos]}' -> '{out[pos]}'")
    else:
        print("  No character differences found")

    # Check if there's a substring replacement
