inputs = ['zbixze', 'gukjv', 'afkcv', 'kba', 'gx']
outputs = ['zbgfzze', 'gukjv', 'beafkcv', 'kbeafac', 'geaf']

print("Detailed character-by-character comparison:")

for i, (inp, out) in enumerate(zip(inputs, outputs)):
    print(f"\nExample {i}: '{inp}' -> '{out}'")
    if inp == out:
        print("  No change")
        continue

    # Find where they start to differ
    min_len = min(len(inp), len(out))
    for j in range(min_len):
        if inp[j] != out[j]:
            print(f"  First difference at position {j}: '{inp[j]}' -> '{out[j]}'")
            break

    # Show the complete transformation
    print(f"  Full transformation: '{inp}' -> '{out}'")

    # Check if there's a simple pattern
    if len(out) > len(inp):
        # Check if we're adding at the beginning
        if out.startswith(inp) and len(out) == len(inp) + 2:
            print(f"  Adding prefix: '{out[:2]}'")
        # Check if we're adding at the end  
        elif out.endswith(inp) and len(out) == len(inp) + 2:
            print(f"  Adding suffix: '{out[-2:]}'")
        # Check if we're inserting somewhere
        else:
            print(f"  Complex insertion")
    elif len(out) < len(inp):
        print(f"  Removing characters")
    else:
        print(f"  Same length - character substitution")

